it('feeds a ToolRegistry schema rejection back as a tool_result so the model can correct its call', async () => {
  const registry = new ToolRegistry();
  const executedInputs: Array<Record<string, unknown>> = [];
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async input => {
      executedInputs.push(input);
      return `sunny in ${String(input.location)}`;
    }
  );
  expect(executedInputs).toEqual([]);

  const seenParams: SendMessageParams[] = [];
  const provider = scriptedProvider([
    [{type: 'tool_use', toolCall: {id: 'call-bad', name: 'get_weather', input: {location: 123}}}, STOP_FOR_TOOL],
    [
      {type: 'tool_use', toolCall: {id: 'call-good', name: 'get_weather', input: {location: 'Berlin'}}},
      STOP_FOR_TOOL,
    ],
    [{type: 'text', text: 'Berlin is sunny'}, STOP_DONE],
  ]);
  const recordingProvider: AIProvider = {
    sendMessage(params) {
      seenParams.push({...params, messages: [...params.messages]});
      return provider.sendMessage(params);
    },
    generateStructured: provider.generateStructured,
  };

  const orchestrator = createChatOrchestrator(recordingProvider, promptBuilder, registry);
  const reply = await orchestrator.processMessage(createSession('weather?'));
  const round2Messages = seenParams[1]?.messages ?? [];
  const lastRound2Message = round2Messages.at(-1);
  const round2ToolResults = lastRound2Message?.content;

  expect({
    reply,
    executedInputs,
    round2ToolResult: Array.isArray(round2ToolResults) ? round2ToolResults[0] : undefined,
  }).toEqual({
    reply: 'Berlin is sunny',
    executedInputs: [{location: 'Berlin'}],
    round2ToolResult: {
      type: 'tool_result',
      toolUseId: 'call-bad',
      content: expect.stringMatching(/Invalid input for tool "get_weather".*location.*string/),
    },
  });
});

